function runMiddleware(handlers, ctx) {
  let i = 0;
  function next() {
    if (ctx.isAborted()) return;
    if (i >= handlers.length) return;
    const h = handlers[i++]; h(ctx, next);
  }
  next();
}
function makeCtx() {
  const logs = []; let aborted = false;
  return { logs, abort() { aborted = true; }, isAborted() { return aborted; } };
}
const ctx = makeCtx();
runMiddleware([
  (c, n) => { c.logs.push("auth"); n(); },
  (c, n) => { c.logs.push("ratelimit: 超限，中断"); c.abort(); n(); },
  (c, n) => { c.logs.push("handler(不应执行)"); n(); },
  (c, n) => { c.logs.push("after(不应执行)"); n(); },
], ctx);
console.log(ctx.logs.join(" -> "));
console.log("aborted =", ctx.isAborted());
